package org.grebenyk.airhub.ui;

import org.grebenyk.airhub.db.Db;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import javax.swing.table.TableModel;
import javax.swing.table.TableRowSorter;
import java.awt.*;
import java.sql.Date;
import java.sql.SQLException;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Generic database table form: view, sort, search, filter, add, edit, delete.
 * Columns come from query metadata; the first table column must be id (generated by the database).
 */
public class TableForm extends JInternalFrame {
    private static final Map<String, String> HEADERS = Map.ofEntries(
            Map.entry("id", "ID"), Map.entry("login", "Логін"), Map.entry("password", "Пароль"), Map.entry("role", "Роль"),
            Map.entry("can_edit", "Редагування"), Map.entry("can_reports", "Звіти"),
            Map.entry("name", "Назва"), Map.entry("val", "Значення"), Map.entry("description", "Опис"), Map.entry("country", "Країна"),
            Map.entry("ts", "Час"), Map.entry("action", "Дія"), Map.entry("details", "Деталі"),
            Map.entry("flight_no", "Рейс"), Map.entry("airline_id", "Авіакомпанія"), Map.entry("type", "Тип"),
            Map.entry("city", "Місто"), Map.entry("sched_time", "Час за розкладом"), Map.entry("gate", "Гейт"),
            Map.entry("status", "Статус"));
    private static final int WINDOW_WIDTH = 1000, WINDOW_HEIGHT = 450;
    private static final int DATE_FIELD_COLUMNS = 8, SEARCH_FIELD_COLUMNS = 12, EDIT_FIELD_COLUMNS = 20;
    private static final int FORM_GAP = 5;
    private static final int ID_COL = 0;

    private final String table, dateCol;
    private final Map<String, String[]> choices;
    // column -> "SELECT id, name" query of a reference table; the table shows the name instead of the id
    private final Map<String, String> lookups;
    private final Map<String, Map<Object, String>> lookupValues = new HashMap<>();
    private final JTable grid = new JTable();
    private final JTextField from = new JTextField(DATE_FIELD_COLUMNS), to = new JTextField(DATE_FIELD_COLUMNS);
    private final JTextField search = new JTextField(SEARCH_FIELD_COLUMNS);
    private final JComboBox<String> searchCol = new JComboBox<>();
    // indexes of searchable columns (columns that have a filter are excluded)
    private final List<Integer> searchable = new ArrayList<>();
    private final Map<String, JComboBox<String>> filters = new LinkedHashMap<>();

    TableForm(String title, String table, boolean editable, String dateCol, Map<String, String[]> choices) {
        this(title, table, editable, dateCol, choices, Map.of());
    }

    /**
     * @param dateCol column for the date range filter, or null
     * @param choices columns with a list of allowed values (for filtering and editing)
     * @param lookups columns referencing a reference table: column -> "SELECT id, name ..."
     */
    TableForm(String title, String table, boolean editable, String dateCol, Map<String, String[]> choices,
              Map<String, String> lookups) {
        super(title, true, true, true, true);
        this.table = table;
        this.dateCol = dateCol;
        this.choices = choices;
        this.lookups = lookups;
        grid.setAutoCreateRowSorter(true);

        JPanel toolbar = new JPanel(new FlowLayout(FlowLayout.LEFT));
        toolbar.add(new JLabel("Пошук:"));
        toolbar.add(searchCol);
        toolbar.add(search);
        toolbar.add(Ui.button("Знайти", null, e -> reload()));
        search.addActionListener(e -> reload());
        if (editable && Db.user.canEdit()) {
            toolbar.add(Ui.button("Додати", "FileChooser.newFolderIcon", e -> edit(true)));
            toolbar.add(Ui.button("Змінити", "FileChooser.detailsViewIcon", e -> edit(false)));
            toolbar.add(Ui.button("Видалити", null, e -> delete()));
        }

        JPanel filter = new JPanel(new FlowLayout(FlowLayout.LEFT));
        if (dateCol != null) {
            filter.add(new JLabel("Період з (РРРР-ММ-ДД):"));
            filter.add(from);
            filter.add(new JLabel("по:"));
            filter.add(to);
        }
        choices.forEach((col, values) -> {
            JComboBox<String> cb = new JComboBox<>();
            cb.addItem("(усі)");
            for (String v : values) cb.addItem(v);
            filters.put(col, cb);
            filter.add(new JLabel(header(col) + ":"));
            filter.add(cb);
        });

        JPanel top = new JPanel(new GridLayout(0, 1));
        top.add(toolbar);
        if (filter.getComponentCount() > 0) top.add(filter);
        add(top, BorderLayout.NORTH);
        add(new JScrollPane(grid));
        setSize(WINDOW_WIDTH, WINDOW_HEIGHT);

        reload();
        searchCol.addItem("(усі поля)");
        for (int i = 0; i < grid.getModel().getColumnCount(); i++) {
            String col = grid.getModel().getColumnName(i).toLowerCase();
            if (col.equals(dateCol) || choices.containsKey(col)) continue;
            searchable.add(i);
            searchCol.addItem(header(col));
        }
        Db.log("ВІДКРИТТЯ", table);
    }

    private static String header(String col) {
        return HEADERS.getOrDefault(col.toLowerCase(), col);
    }

    private void reload() {
        // WHERE 1=1 lets every filter condition be appended with AND
        StringBuilder sql = new StringBuilder("SELECT * FROM " + table + " WHERE 1=1");
        List<Object> params = new ArrayList<>();
        try {
            if (!from.getText().isBlank()) {
                sql.append(" AND CAST(").append(dateCol).append(" AS DATE) >= ?");
                params.add(Date.valueOf(from.getText().trim()));
            }
            if (!to.getText().isBlank()) {
                sql.append(" AND CAST(").append(dateCol).append(" AS DATE) <= ?");
                params.add(Date.valueOf(to.getText().trim()));
            }
            // item 0 of a filter list is "(усі)", i.e. no condition
            filters.forEach((col, cb) -> {
                if (cb.getSelectedIndex() > 0) {
                    sql.append(" AND ").append(col).append(" = ?");
                    params.add(cb.getSelectedItem());
                }
            });
            loadLookups();
            DefaultTableModel model = Db.query(sql + " ORDER BY id", params.toArray());
            for (int i = 0; i < model.getColumnCount(); i++) {
                Map<Object, String> names = lookupValues.get(model.getColumnName(i).toLowerCase());
                if (names == null) continue;
                for (int r = 0; r < model.getRowCount(); r++) {
                    model.setValueAt(names.get(model.getValueAt(r, i)), r, i);
                }
            }
            grid.setModel(model);
            for (int i = 0; i < grid.getColumnCount(); i++) {
                grid.getColumnModel().getColumn(i).setHeaderValue(header(grid.getModel().getColumnName(i)));
            }
            applySearch();
        } catch (IllegalArgumentException e) {
            // Date.valueOf rejects dates in any other format
            JOptionPane.showMessageDialog(this, "Дата має бути у форматі РРРР-ММ-ДД", "Помилка", JOptionPane.ERROR_MESSAGE);
        } catch (SQLException e) {
            Ui.showError(this, e);
        }
    }

    // reference tables are re-read on every reload so new records (airlines) are available at once
    private void loadLookups() throws SQLException {
        for (var e : lookups.entrySet()) {
            Map<Object, String> names = new LinkedHashMap<>();
            TableModel model = Db.query(e.getValue());
            // query column 0 is the id, column 1 is the name
            for (int r = 0; r < model.getRowCount(); r++) {
                names.put(model.getValueAt(r, 0), String.valueOf(model.getValueAt(r, 1)));
            }
            lookupValues.put(e.getKey(), names);
        }
    }

    @SuppressWarnings("unchecked")
    private void applySearch() {
        String text = search.getText().trim();
        // item 0 is "(усі поля)", so the index in searchable is one less
        int col = searchCol.getSelectedIndex() - 1;
        RowFilter<TableModel, Integer> f = null;
        if (!text.isEmpty()) {
            int[] cols;
            if (col < 0) cols = searchable.stream().mapToInt(Integer::intValue).toArray();
            else cols = new int[]{searchable.get(col)};
            // (?iu) - case-insensitive, including Cyrillic; Pattern.quote - the text is matched literally
            f = RowFilter.regexFilter("(?iu)" + Pattern.quote(text), cols);
        }
        ((TableRowSorter<TableModel>) grid.getRowSorter()).setRowFilter(f);
    }

    private void edit(boolean isNew) {
        TableModel model = grid.getModel();
        int row = -1;
        if (!isNew) {
            if (grid.getSelectedRow() < 0) {
                JOptionPane.showMessageDialog(this, "Оберіть запис");
                return;
            }
            // the row index in the sorted/filtered view is converted to the model index
            row = grid.convertRowIndexToModel(grid.getSelectedRow());
        }
        int n = model.getColumnCount();
        JComponent[] fields = new JComponent[n];
        JPanel form = new JPanel(new GridLayout(0, 2, FORM_GAP, FORM_GAP));
        // the id column is not editable, so the loops start at ID_COL + 1
        for (int i = ID_COL + 1; i < n; i++) {
            String col = model.getColumnName(i).toLowerCase();
            String value = row < 0 || model.getValueAt(row, i) == null ? "" : model.getValueAt(row, i).toString();
            String[] options = choices.get(col);
            if (options == null && lookupValues.containsKey(col)) options = lookupValues.get(col).values().toArray(String[]::new);
            if (options != null) {
                JComboBox<String> cb = new JComboBox<>(options);
                if (row >= 0) cb.setSelectedItem(value);
                fields[i] = cb;
            } else {
                fields[i] = new JTextField(value, EDIT_FIELD_COLUMNS);
            }
            form.add(new JLabel(header(col) + ":"));
            form.add(fields[i]);
        }
        int answer = JOptionPane.showConfirmDialog(this, form, isNew ? "Новий запис" : "Зміна запису",
                JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (answer != JOptionPane.OK_OPTION) return;

        List<String> cols = new ArrayList<>();
        List<Object> values = new ArrayList<>();
        for (int i = ID_COL + 1; i < n; i++) {
            cols.add(model.getColumnName(i));
            String v;
            if (fields[i] instanceof JComboBox<?> cb) v = (String) cb.getSelectedItem();
            else v = ((JTextField) fields[i]).getText().trim();
            // for a reference column the selected name is converted back to the id
            Map<Object, String> names = lookupValues.get(model.getColumnName(i).toLowerCase());
            values.add(v == null || v.isEmpty() ? null : names == null ? v : idOf(names, v));
        }
        try {
            if (isNew) {
                String placeholders = String.join(", ", Collections.nCopies(cols.size(), "?"));
                Db.update("INSERT INTO " + table + " (" + String.join(", ", cols) + ") VALUES (" + placeholders + ")",
                        values.toArray());
                Db.log("ДОДАВАННЯ", table + ": " + values);
            } else {
                Object id = model.getValueAt(row, ID_COL);
                List<Object> params = new ArrayList<>(values);
                params.add(id);
                Db.update("UPDATE " + table + " SET " + String.join(" = ?, ", cols) + " = ? WHERE id = ?", params.toArray());
                Db.log("ЗМІНА", table + " id=" + id + ": " + values);
            }
            reload();
        } catch (SQLException e) {
            Ui.showError(this, e);
        }
    }

    /** Id of a reference table record by its name (names are unique). */
    private static Object idOf(Map<Object, String> names, String name) {
        return names.entrySet().stream()
                .filter(e -> e.getValue().equals(name))
                .map(Map.Entry::getKey)
                .findFirst().orElse(null);
    }

    private void delete() {
        if (grid.getSelectedRow() < 0) {
            JOptionPane.showMessageDialog(this, "Оберіть запис");
            return;
        }
        TableModel model = grid.getModel();
        int row = grid.convertRowIndexToModel(grid.getSelectedRow());
        Object id = model.getValueAt(row, ID_COL);
        int answer = JOptionPane.showConfirmDialog(this, "Видалити запис ID=" + id + "?", "Видалення", JOptionPane.YES_NO_OPTION);
        if (answer != JOptionPane.YES_OPTION) return;
        List<Object> values = new ArrayList<>();
        for (int i = 0; i < model.getColumnCount(); i++) values.add(model.getValueAt(row, i));
        try {
            Db.update("DELETE FROM " + table + " WHERE id = ?", id);
            Db.log("ВИДАЛЕННЯ", table + ": " + values);
            reload();
        } catch (SQLException e) {
            Ui.showError(this, e);
        }
    }
}
